'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rp=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0),params=new URLSearchParams(location.hash.slice(1));const L=window.THLaundryLabel,UI=window.THLaundryUI;let room,services,order,busy=false;const roomToken=params.get('room'),orderKey=params.get('key'),orderId=params.get('order');
function message(s,error=false){$('#message').className='alert '+(error?'error':'success');$('#message').textContent=THCopy.error(s);}
async function api(path,data,secret){const res=await fetch('/api/portal/'+path,{method:data?'POST':'GET',cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(20000),headers:{'Authorization':'Bearer '+(secret||roomToken||orderKey),'Content-Type':'application/json','X-Top-Hills':'1'},body:data?JSON.stringify(data):undefined});const v=await res.json();if(!res.ok)throw Error(v.error||'Permintaan belum tersimpan. Coba kembali.');return v;}
const select=(name,label,items,value)=>`<label>${label}<select name="${name}">${items.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
function fields(c={}){return `<div class="grid"><label>Nama pelanggan<input name="name" required minlength="2" maxlength="100" autocomplete="name" value="${esc(c.name)}"></label><label>Nomor WhatsApp<input name="contact" required type="tel" autocomplete="tel" placeholder="08…" value="${esc(c.contact)}"></label>${select('relationship','Hubungan dengan kamar',[['Penghuni','Penghuni kamar'],['Tamu','Tamu penginapan'],['Keluarga','Keluarga / pendamping']],c.relationship)}${select('method','Penyerahan laundry',[['pickup','Dijemput di kamar'],['dropoff','Saya antar ke counter']],c.method)}${UI.picker(services,c)}<label class="full">Instruksi khusus<textarea name="note" maxlength="1000" placeholder="Contoh: pisahkan pakaian putih; hubungi sebelum menjemput.">${esc(c.note)}</textarea></label></div>`;}
function serviceHelp(){document.querySelectorAll('[data-service-count]').forEach(el=>{el.textContent=el.closest('form').querySelectorAll('[name=serviceIds]:checked').length+' paket dipilih';});}
function pricePanel(o){
 if(!o.price)return `<p class="muted">Paket dipilih: ${esc(UI.ids(o.customer).map(id=>services.find(s=>s.id===id)?.name||id).join(' + '))}. Menunggu hasil timbang petugas.</p>`;
 const canApprove=!o.priceApproved&&o.customerRevision===o.acceptedRevision&&!['CANCELLED','CANCEL REQUESTED','RETURN REQUESTED','VOIDED','ON HOLD'].includes(o.status);
 return `<section class="price-review"><h2>Hasil timbang & harga</h2>${UI.priceTable(o.price)}${o.processingException&&!o.priceApproved?`<div class="alert danger">${UI.icon('danger')}<span><strong>Petugas sudah mulai bekerja melalui pengecualian.</strong><br>${esc(o.processingException.reason)}<br>Konfirmasi harga Anda masih ditunggu.</span></div>`:''}${o.priceApproved?UI.badge('APPROVED','Harga sudah disetujui'):canApprove?'<button class="primary" id="approve">Setujui rincian & harga final</button>':`<p class="alert warning">${o.customerRevision!==o.acceptedRevision?'Menunggu revisi diterima petugas.':'Konfirmasi belum tersedia pada tahap '+esc(L(o.status))+'.'}</p>`}</section>`;
}
function roomCard(r){return `<div class="card room"><div><small>Lokasi dari QR · terkunci</small><b>${esc(r.id)}</b><p>Gedung ${esc(r.building)} · Lantai ${esc(r.floor||'belum diatur')} · ${esc(r.roomType)}</p>${r.checkout?`<small>Checkout ${esc(new Date(r.checkout).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}))}</small>`:''}</div><span class="tag">Kamar Anda</span></div>`;}
function form(){let saved={};try{saved=JSON.parse(sessionStorage.getItem('th-qr-draft:'+roomToken)||'{}')}catch{};$('#view').innerHTML=`<span class="eyebrow">01 / Check-in</span><h1>Laundry baru, tanpa antre.</h1><p class="muted">Lengkapi pesanan. Petugas akan mengonfirmasi sebelum mengambil atau menerima barang Anda.</p>${roomCard(room)}<div class="steps"><span class="on">Isi pesanan</span><span>Diterima petugas</span><span>Timbang & konfirmasi</span></div><form id="checkin" class="card"><h2>Pesanan Anda</h2>${fields(saved)}<p class="alert info">Belum ada penagihan saat check-in. Nominal mengikuti rincian timbang tiap paket. Anda dapat memeriksa dan menyetujui harga melalui tautan order. Jika Anda belum merespons, petugas dapat melanjutkan proses dengan alasan yang tercatat.</p><label class="check"><input type="checkbox" required> Saya memastikan kamar dan data pesanan sudah benar.</label><div class="row" style="margin-top:22px"><button class="primary" type="submit">Kirim check-in</button><small>Satu pengiriman = satu order</small></div></form>`;serviceHelp();$('#checkin').addEventListener('change',serviceHelp);$('#checkin').addEventListener('input',()=>sessionStorage.setItem('th-qr-draft:'+roomToken,JSON.stringify(UI.serialize($('#checkin'),true))));$('#checkin').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const btn=$('#checkin button');btn.disabled=true;btn.textContent='Mengirim & memeriksa hasil…';const k='th-qr-submit:'+roomToken;let secret=sessionStorage.getItem(k);if(!secret){secret=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');sessionStorage.setItem(k,secret);}try{const result=await api('submit',{...UI.serialize(e.target),orderToken:secret});sessionStorage.removeItem('th-qr-draft:'+roomToken);sessionStorage.removeItem(k);location.hash='order='+result.order.id+'&key='+secret;location.reload();}catch(err){message(err.message+' Anda dapat mencoba lagi. Pesanan yang sama tidak akan dibuat dua kali.',true);btn.disabled=false;btn.textContent='Periksa & kirim ulang';}finally{busy=false}};}
async function action(action,extra={}){if(busy)return;busy=true;try{const v=await api('action',{id:order.id,revision:order.revision,mutationId:crypto.randomUUID(),action,...extra},orderKey);order=v.order;renderOrder();message('Perubahan tersimpan.');}catch(e){message(e.message,true);}finally{busy=false}}
function renderOrder(){const o=order,canRevise=!['IN PROCESS','READY FOR HANDOVER','COMPLETED','CANCEL REQUESTED','RETURN REQUESTED','CANCELLED','VOIDED','ON HOLD'].includes(o.status)&&!(o.pay.received>0);$('#view').innerHTML=`<span class="eyebrow">Pesanan tersimpan</span><h1>${esc(o.customer.name)}, check-in Anda tercatat.</h1><p class="muted">Simpan tautan halaman ini untuk membuka order yang sama dari perangkat lain. Jangan membagikannya kepada orang lain.</p><div class="row"><button id="copy">Salin tautan order</button><button id="refresh">Perbarui status</button></div>${roomCard(o.room)}<div class="card"><label>Foto / bukti tambahan (opsional)<input id="customer-photo" ${['IN PROCESS','READY FOR HANDOVER','COMPLETED','CANCEL REQUESTED','RETURN REQUESTED','CANCELLED','VOIDED','ON HOLD'].includes(o.status)?'disabled':''} type="file" accept="image/jpeg,image/png,application/pdf"></label><small>JPG, PNG, PDF · maksimal 5 MB. Bukti pembayaran tetap perlu verifikasi petugas.</small></div><div class="card"><div class="row spread"><strong>${esc(o.id)}</strong>${UI.badge(o.status)}</div><p>${o.acceptedName?'Diterima oleh '+esc(o.acceptedName):'Menunggu petugas menerima pesanan'}</p><div class="status-grid"><div><small>Identitas</small>${UI.badge(o.identity)}</div><div><small>Pembayaran</small>${UI.badge(o.pay.status)}</div><div><small>Perubahan pesanan</small><strong>${o.acceptedRevision===o.customerRevision?'Sudah diperiksa petugas':'Menunggu pemeriksaan petugas'}</strong></div></div>${pricePanel(o)}${o.ref.status!=='NONE'?`<p class="alert">Pengembalian dana ${esc(L(o.ref.status))} · ${rp(o.ref.amount)}</p>`:''}<p class="muted">WhatsApp belum terhubung. Status terbaru tersedia di halaman ini.</p></div><div class="card"><h2>Bukti perjalanan laundry</h2><div class="row">${(o.proofs||[]).map(p=>`<button data-proof="${esc(p.id)}">${esc(p.label)}</button>`).join('')||'<p class="muted">Foto penerimaan dan hasil timbang akan tampil setelah dicatat petugas.</p>'}</div><div id="proof-preview"></div></div>${!['COMPLETED','CANCELLED','VOIDED'].includes(o.status)?`${canRevise?`<details class="card"><summary>Ubah informasi pesanan</summary><form id="revise">${fields(o.customer)}<p>Revisi perlu diterima kembali oleh petugas.</p><button type="submit">Kirim revisi</button></form></details>`:'<p class="alert info">Pesanan sedang ditangani. Hubungi petugas bila ada perubahan.</p>'}<div class="row">${o.identity!=='CONFIRMED'?'<button id="confirm">Ini pesanan saya</button><button id="reject" class="danger">Bukan milik saya</button>':''}<button id="cancel" class="danger">Ajukan pembatalan</button></div>`:''}`;document.querySelectorAll('[data-proof]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await fetch('/api/portal/proof?orderId='+encodeURIComponent(o.id)+'&id='+encodeURIComponent(b.dataset.proof),{cache:'no-store',headers:{Authorization:'Bearer '+orderKey}});if(!r.ok)throw Error('Bukti belum dapat dibuka.');const u=URL.createObjectURL(await r.blob());const img=new Image();img.alt=b.textContent;img.style='max-width:100%;border-radius:12px;margin-top:16px';img.onload=()=>URL.revokeObjectURL(u);img.src=u;$('#proof-preview').replaceChildren(img);}catch(e){message(e.message,true)}finally{b.disabled=false}});$('#customer-photo').onchange=async e=>{const f=new FormData();f.set('orderId',o.id);f.set('file',e.target.files[0]);try{const r=await fetch('/api/portal/proof',{method:'POST',headers:{Authorization:'Bearer '+orderKey,'X-Top-Hills':'1'},body:f});const v=await r.json();if(!r.ok)throw Error(v.error);await loadOrder();message('Bukti tersimpan untuk diperiksa petugas.');}catch(e){message(e.message,true)}};$('#copy').onclick=()=>navigator.clipboard.writeText(location.href).then(()=>message('Tautan order disalin.')).catch(()=>message('Salin alamat halaman dari browser Anda.',true));$('#refresh').onclick=loadOrder;$('#approve')?.addEventListener('click',()=>action('approve-price'));$('#revise')?.addEventListener('submit',e=>{e.preventDefault();try{action('revise',UI.serialize(e.target))}catch(err){message(err.message,true)}});$('#cancel')?.addEventListener('click',()=>{const reason=prompt('Alasan pembatalan (minimal 5 karakter):');if(reason)action('cancel',{reason})});$('#confirm')?.addEventListener('click',()=>{try{action('confirm-identity',$('#revise')?UI.serialize($('#revise')):o.customer)}catch(e){message(e.message,true)}});$('#reject')?.addEventListener('click',()=>{if(confirm('Laporkan bahwa barang ini bukan milik Anda?'))action('reject-ownership')});$('#revise')?.addEventListener('change',serviceHelp);serviceHelp();}
async function loadOrder(){try{const v=await api('order?id='+encodeURIComponent(orderId),null,orderKey);order=v.order;services=THServices.catalog();renderOrder();}catch(e){message(e.message,true)}}
(async()=>{try{if(orderId&&orderKey){await loadOrder();return;}if(!roomToken){$('#view').innerHTML='<h1>Pindai QR di kamar Anda.</h1><p>Halaman check-in dibuka dari QR khusus kamar. Minta bantuan petugas apabila QR tidak terbaca.</p>';return;}const data=await api('room');room=data.room;services=data.services;form();}catch(e){$('#view').innerHTML='<h1>QR belum dapat digunakan.</h1><p>'+esc(e.message)+'</p><p>Hubungi petugas Top Hills untuk check-in dibantu.</p>';}})();
